  tip(/^(Trades replayed|Your exits|Best rule, in hindsight|Exit efficiency)$/, (el, title, bd) => { if (view() !== 'exit') return null; const E = ex(); if (!E) return null; const a = E.act, b = E.best, n = E.used.length, v = lbl(el.querySelector('b') || el);
    if (title === 'Trades replayed') return card({ title, chip: n < EX_WF_MIN ? `under ${EX_WF_MIN}: no walk-forward test` : `enough for the walk-forward test (at least ${EX_WF_MIN})`, tone: n < EX_WF_MIN ? 'warn' : '', value: esc(v), vlabel: 'Closed trades replayed', plain: esc(bd), secs: [sec('The rules of the count', tbl([row('Cap', `the ${EX_CAP} most recent trades`), row('Minimum for the tool', '5 replayable trades'), row('Left out now', `${E.skip.hist + E.skip.off + E.skip.short}`)]))], use: 'The more trades, the less one lucky trade moves the table.' });
    if (title === 'Your exits') return card({ title, chip: a.sumR > 0 ? 'net positive in R' : a.sumR < 0 ? 'net negative in R' : 'flat', tone: a.sumR > 0 ? 'ok' : a.sumR < 0 ? 'bad' : '', value: `${S1(a.sumR)} R`, vlabel: 'Total of your exits, in R', sub: `${S1(a.avgR, 2)} R a trade · ${a.win.toFixed(0)}% winners`, plain: esc(bd), secs: [sec('Your row of the table', tbl([row('Total R', S1(a.sumR)), row('Average R', S1(a.avgR, 2)), row('Win rate', a.win.toFixed(0) + '%'), row('Max drawdown', a.dd.toFixed(1) + ' R'), row('P&L', (a.usd < 0 ? '−' : '+') + '$' + Math.abs(a.usd).toFixed(0))]))], watch: 'R weights every trade the same; dollars weight by size, so the two signs can differ.', use: 'This is the line the other rules have to beat.' });
    if (title === 'Best rule, in hindsight') return card({ title, chip: b.avgR > EX_ODD_R ? `above ${EX_ODD_R} R a trade: check the data first` : 'picked after the fact: a description, not a recommendation', tone: b.avgR > EX_ODD_R ? 'warn' : '', value: `${S1(b.sumR)} R`, vlabel: RNAME(b.k), sub: `${S1(b.sumR - a.sumR)} R against your exits`, plain: esc(bd), secs: [sec('The best row', tbl([row('Rule', esc(RNAME(b.k) + ': ' + b.desc)), row('Total R', S1(b.sumR)), row('Average R', S1(b.avgR, 2)), row('Win rate', b.win.toFixed(0) + '%'), row('Max drawdown', b.dd.toFixed(1) + ' R'), row('Verdict', E.vd ? esc(E.vd[1]) : '—')]))], watch: 'The best of 8 rules, chosen after seeing the result, overstates its edge. The walk-forward verdict says whether it held on trades it did not see.', use: 'Read it with the verdict, never alone.' });
    const eff = E.eff; return card({ title, chip: eff == null ? 'no trade was ever in profit' : eff < 0 ? 'negative: exits closed below entry after being in profit' : Math.round(eff) < 30 ? 'under 30%: profits were often given back' : '30% or more of the best profit kept', tone: eff == null ? '' : eff >= 0 && Math.round(eff) < 30 || eff < 0 ? 'warn' : '', value: eff == null || eff < 0 ? '—' : eff.toFixed(0) + '%', vlabel: 'Share of the best open profit your exits kept', plain: esc(bd), secs: [sec('How it is measured', tbl([row('Best open profit', 'the MFE: the maximum favourable excursion while you held the trade'), row('Captured', 'your exit against the MFE, per trade, limited to −100% … +100%, then averaged'), row('A sell', 'is measured on the ask')]))], use: 'A low figure means trades went well into profit and were closed far from the best point: look at where you take profit.' }); }, { within: '#obs' });

  // ---- text blocks under the KPIs ----
  claim('#obsBody > p.small:not(.muted):not(.ex-skip):not(.ex-note)', el => { const E = ex(), t = lbl(el); if (view() !== 'exit' || !E) return textCard(el);
    return card({ title: 'In hindsight', chip: 'the best rule against yours, and what chance allows', tone: '', plain: esc(t), secs: [sec('The test behind it', tbl([row('Per-trade difference', 'the rule\'s R minus yours, trade by trade'), row('Margin', `p below 0.05 / 8, for the best of 8 rules`), row('Kept', E.eff == null || E.eff < 0 ? '—' : E.eff.toFixed(0) + '% of the best open profit')]))], watch: 'Trades that overlap in time are not fully independent, and the best rule regresses on new trades more often than not.', use: 'Take the sentence as a question to test forward, not an instruction.' }); }, ['exit']);
  add('#obsBody .ex-term', el => { const bd2 = body(el), ttl = (el.dataset.tip || '').split('|')[0];
    if (/^Paired t/.test(ttl)) { const E = ex(), d = E && E.best ? E.best.Rs.map((r, i) => r - E.act.Rs[i]) : [], t = d.length > 1 ? labT(d) : null;
      return card({ title: 'Paired t', chip: 'the size of the difference against its noise', tone: '', value: t == null ? '—' : t.toFixed(1), vlabel: 'Paired t, best rule against yours', plain: esc(bd2), secs: [sec('Reading it', tbl([row('|t| beyond 2', 'a single test would rarely be chance'), row('Here', `the best of 8 rules was picked afterwards: the bar is p below 0.05 / 8, not |t| > 2`)]))], use: 'Do not read a large t on the best rule as proof: it was chosen because it was the largest.' }); }
    return card({ title: 'Base R', chip: 'the unit of the map', tone: '', plain: esc(bd2), use: 'Compare cells of the same row and column, not by how bright one is.' }); });

  // ---- the stop x target map ----
  add('#obsBody .ex-more .bh-card > h3', el => { const t = lbl(el), E = ex();
    if (/^Stop/.test(t)) return card({ title: 'Stop × target map', chip: 'every stop and target combination, on the same entries', tone: '', plain: 'Each cell replays your entries with one stop distance (rows) and one target (columns) and adds up the R. Cells are counted in R of their own stop, so a wide stop is not favoured for risking more.', secs: [sec('The grid', tbl([row('Stops', EX_SM.map(x => x + 'R').join(' · ')), row('Targets', EX_TM.map(x => x == null ? 'none (24h)' : x + '× stop').join(' · '))]))], watch: 'A lone bright cell among dark ones is luck; a bright neighbourhood is more believable.', use: 'Look for a region, not a cell.' });
    const w = E && E.wf; return card({ title: 'Walk-forward check', chip: w ? `chosen on ${w.nA} trades, tested on ${w.nB}` : `needs at least ${EX_WF_MIN} replayed trades`, tone: '', plain: 'Choose the best rule on the older half of your trades, then score it on the newer half it never saw. A rule that was only lucky in the first half fades in the second.', secs: w ? [sec('The split', tbl([row('Older trades', String(w.nA)), row('Chosen', RNAME(w.pick) + ', ' + S1(w.inA) + ' R in hindsight'), row('Newer trades', String(w.nB)), row('The rule on them', S1(w.outB) + ' R'), row('Your exits on them', S1(w.mineB) + ' R')]))] : [sec('The minimum', p(`At least ${EX_WF_MIN} replayed trades, and at least 4 in each half.`))], use: 'This is the test that matters more than the table.' }); });
  add('#obsBody .ex-grid > span', el => { const t = lbl(el), c = el.classList.contains('c');
    if (!c) return card({ title: t, chip: el.classList.contains('r') ? 'the stop distance of a row' : 'the target of a column', tone: '', plain: /none/.test(t) ? 'No target: the trade exits after 24 hours of open market, or at the stop.' : /stop ↓/.test(t) ? 'Rows are stop distances in base R, columns are targets as a multiple of that stop.' : /^stop/.test(t) ? `The stop of this row: ${t.replace('stop ', '')} of the trade's base R (your initial stop, or the volatility stop).` : `The target of this column: ${t.replace('× stop', '')} times the stop of the row.`, use: 'Read across a row to see what a target changes, down a column to see what a stop changes.' });
    const v = num(t, 0), best = el.classList.contains('best'), [ttl] = (el.dataset.tip || '').split('|');
    return card({ title: ttl || 'Cell', chip: v > 0 ? 'gained in R on the same entries' : v < 0 ? 'lost in R on the same entries' : 'flat', tone: v > 0 ? 'ok' : v < 0 ? 'bad' : '', value: `${S1(v)} R`, vlabel: 'Total R on the replayed trades, equal risk', sub: best ? 'the best cell of the map, in hindsight' : '', plain: esc(body(el)), watch: best ? 'The best cell of a grid of 20 is the best partly by chance.' : '', use: 'Trust a cell only if its neighbours look alike.' }); });
  claim('#obsBody .ex-gleg', el => card({ title: 'How to read the map', chip: 'colour, outline and unit', tone: '', plain: esc(lbl(el)), secs: [sec('The code', tbl([row('Green / red', 'gained / lost'), row('Stronger colour', 'a larger total'), row('Outline', 'the best cell'), row('Unit', 'R of the cell\'s own stop, so every cell risks the same')]))], use: 'A bright neighbourhood is more believable than one bright cell.' }), ['exit']);
  claim('#obsBody .ex-more .bh-card p.small:not(.ex-gleg)', el => { const E = ex(), w = E && E.wf; return card({ title: 'Walk-forward result', chip: E && E.vd ? E.vd[1] : '', tone: E && E.vd ? exTone(E.vd[0]) : '', plain: esc(lbl(el)), secs: w ? [sec('The figures', tbl([row('Older trades', String(w.nA)), row('Chosen', RNAME(w.pick) + ', ' + S1(w.inA) + ' R'), row('On the newer trades', S1(w.outB) + ' R'), row('Your exits on them', S1(w.mineB) + ' R')]))] : [], watch: 'One split on a small sample: this describes the past, it does not predict the next trades.', use: 'Change nothing on this alone; test it forward.' }); }, ['exit']);
  add('#obsBody .ex-kind-w h3', el => card({ title: 'Where you lose', chip: 'your trades by how they actually ended', tone: '', plain: 'Your trades grouped by the way they closed (by hand, stop loss, take profit, trail, break-even, time stop, stop-out), with the result of the best rule on the same trades.', secs: [sec('The reading', tbl([row('Sorted', 'from the type that lost the most'), row('Minimum', `${typeof EX_KIND_MIN === 'number' ? EX_KIND_MIN : 3} trades of a type, or no average is shown`)]))], use: 'It says where the losses came from, not what the next trades will do.' }));
  claim('#obsBody .ex-kind-w > p.small', el => card({ title: 'Reading the exit types', chip: 'hindsight on a few trades', tone: '', plain: esc(lbl(el)), use: 'Look for the type that carries most of the loss: that is the exit habit to examine.' }), ['exit']);
  claim('#obsBody > p.ex-per-cap', el => { const E = ex(); return card({ title: 'Trades shown', chip: 'the replayed trades, most recent first', tone: '', plain: esc(lbl(el)), secs: E ? [sec('Counts', tbl([row('Replayed', String(E.per.length)), row('Shown', String(Math.min(12, E.per.length)))]))] : [], use: 'The table below lists the trades one by one; the verdict uses all of them.' }); }, ['exit']);
  claim('#obsBody > p.small.muted:not(.ex-per-cap)', el => card({ title: 'What the replay does and does not include', chip: 'costs, fills and window', tone: '', plain: esc(lbl(el)), secs: [sec('The rules of the replay', tbl([row('Commission', 'the one your trade paid'), row('Spread', 'the normal spread; a sell exits on the ask'), row('Slippage', 'none'), row('Stops', 'fill at the level, unless the price gapped through it'), row('Time stops', 'count minutes of open market')]))], watch: 'The best of eight rules after the fact overstates its edge.', use: 'Test any rule forward before adopting it.' }), ['exit']);
  claim('#obsBody > .empty, #obsBody .ex-more + .empty', el => card({ title: /^No closed trades/.test(lbl(el)) ? 'No closed trades yet' : 'Too few replayable trades', chip: 'Exit Lab needs at least 5 replayable trades', tone: '', plain: esc(lbl(el)), secs: [sec('Why a trade is not replayed', tbl([row('Price not on the bar path', 'its fill is further from the bars than spread + tolerance'), row('Older than the loaded history', 'no bars before it'), row('Under 15 minutes of price', 'nothing to replay')]))], use: 'Close a few trades and come back, or try the sample trader to see how the tool reads.' }), ['exit']);
  add('#obsBody .empty button.link[data-ex-sample]', () => card({ title: 'Try it with a sample trader', chip: 'loads 40 synthetic trades', tone: '', plain: 'Fills Exit Lab with a sample trader: 40 random entries that take a small win and let losses run to the stop, each risking $100. It has no edge, so what you see are the costs and the shape of the tool.', use: 'Use it to learn the tables; switch back to My trades for the real question.' }), { control: true });
